use vstd::prelude::*;

verus! {

fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
    ensures
        // Length: empty stays empty; otherwise 2n-1
        res@.len() == if numbers@.len() == 0 { 0 } else { 2 * numbers@.len() - 1 },

        // Even indices are original elements in order
        forall|k: int|
            0 <= k < numbers@.len()
            ==> res@[2 * k] == numbers@[k],

        // Odd indices are delimiters (only when there is room for odd positions)
        forall|k: int|
            0 <= k < numbers@.len() - 1
            ==> res@[2 * k + 1] == delim,

        // No trailing delimiter: last element equals last input when non-empty
        (numbers@.len() > 0 ==> res@[res@.len() - 1] == numbers@[numbers@.len() - 1])
{
    let mut res: Vec<i32> = Vec::new();

    let n: usize = numbers.len();
    if n == 0 {
        return res;
    }

    let mut i: usize = 0;
    while i < n
        invariant
            // progress + bounds
            0 <= i as int <= numbers@.len(),

            // length after i processed elements:
            // i == 0 => 0
            // i > 0  => 2i - 1
            res@.len() == if i == 0 { 0 } else { 2 * (i as int) - 1 },

            // even slots contain the original elements processed so far
            forall|k: int|
                0 <= k < i as int
                ==> res@[2 * k] == numbers@[k],

            // odd slots are delimiters for the gaps among the processed elements
            forall|k: int|
                0 <= k < i as int - 1
                ==> res@[2 * k + 1] == delim,

            // when we have processed at least one element, last is the last processed element
            (i as int > 0 ==> res@[res@.len() - 1] == numbers@[i as int - 1]),
    {
        // Append the next number
        res.push(numbers[i]);

        // If not the last input element, append delimiter
        if i + 1 < n {
            res.push(delim);
        }

        i += 1;
    }

    res
}

} // verus!